final_stats = {
  const data = transpose(research_data);
  // Filter for only the last epoch available for each run
  const runs = [...new Set(data.map(d =&gt; d.full_name))];
  const last_points = runs.map(name =&gt; {
    const run_points = data.filter(d =&gt; d.full_name === name);
    return run_points.sort((a, b) =&gt; b.epoch - a.epoch)[0];
  });
  // Apply bar plot sorting
  return d3.sort(last_points, (a, b) =&gt; d3.descending(a[sort_metric], b[sort_metric]));
}

