          agents.push({x: Math.random() * width, y: Math.random() * height, theta: Math.random() * Math.PI * 2});
        }
      } else {
        agents = agents.slice(0, settings.N);
      }
    }

    agents = agents.map((a) =&gt; {
      let sumSin = 0, sumCos = 0, count = 0;
      for (const b of agents) {
        let dx = b.x - a.x, dy = b.y - a.y;
        if (dx &gt; width/2) dx -= width;
        if (dx &lt; -width/2) dx += width;
        if (dy &gt; height/2) dy -= height;
        if (dy &lt; -height/2) dy += height;
        if (dx*dx + dy*dy &lt; settings.radius * settings.radius) {
          sumSin += Math.sin(b.theta);
          sumCos += Math.cos(b.theta);
          count++;
        }
      }
      let avgTheta = Math.atan2(sumSin / Math.max(count, 1), sumCos / Math.max(count, 1));

      if (mouse.x &gt; 0) {
        let mdx = mouse.x - a.x, mdy = mouse.y - a.y;
        if (mdx &gt; width/2) mdx -= width;
        if (mdx &lt; -width/2) mdx += width;
        if (mdy &gt; height/2) mdy -= height;
        if (mdy &lt; -height/2) mdy += height;
        const angleToMouse = Math.atan2(mdy, mdx);
        let diff = angleToMouse - avgTheta;
        while (diff &gt; Math.PI) diff -= Math.PI * 2;
        while (diff &lt; -Math.PI) diff += Math.PI * 2;
        avgTheta += diff * (settings.attraction / 10);
      }

      const newTheta = avgTheta + (Math.random() - 0.5) * settings.noise;
      let x = a.x + Math.cos(newTheta) * settings.speed;
      let y = a.y + Math.sin(newTheta) * settings.speed;
      if (x &lt; 0) x += width; if (x &gt;= width) x -= width;
      if (y &lt; 0) y += height; if (y &gt;= height) y -= height;
      return {x, y, theta: newTheta};
    });
  }

  function draw() {
    ctx.fillStyle = "rgba(0, 5, 15, 0.45)";
    ctx.fillRect(0, 0, width, height);
    ctx.lineWidth = 2.5;
    for (const a of agents) {
      const hue = 280 + Math.sin(a.theta) * 45;
      ctx.strokeStyle = `hsla(${hue}, 85%, 65%, 0.8)`;
      ctx.beginPath();
      ctx.moveTo(a.x, a.y);
      ctx.lineTo(a.x - Math.cos(a.theta) * 12, a.y - Math.sin(a.theta) * 12);
      ctx.stroke();
      ctx.fillStyle = `hsla(${hue}, 95%, 75%, 1)`;
      ctx.beginPath();
      ctx.arc(a.x, a.y, 2.2, 0, Math.PI * 2);
      ctx.fill();
    }
    update();
    requestAnimationFrame(draw);
  }
  requestAnimationFrame(draw);
  return canvas;
}






The order-disorder transition in the Vicsek model is a phase transition in a statistical physics sense: below a critical noise threshold the system spontaneously coordinates; above it, the agents are incoherent. The point is not that your data is a flock of birds — it is that a forty-line simulation running in a browser gives you physical intuition about collective behavior that a static diagram cannot. Quarto is how you ship that.
